from flask import jsonify, render_template, request
from app.utils.logging import logger

class AppError(Exception):
    """应用程序自定义异常"""
    def __init__(self, message, status_code=500):
        self.message = message
        self.status_code = status_code
        super().__init__(self.message)

def register_error_handlers(app):
    """注册全局错误处理器"""

    @app.errorhandler(AppError)
    def handle_app_error(error):
        """处理应用程序自定义异常"""
        logger.error(f"应用程序错误: {error.message} (状态码: {error.status_code})")

        # 如果是API请求，返回JSON响应
        if request.is_json:
            return jsonify({
                'success': False,
                'error': error.message,
                'status_code': error.status_code
            }), error.status_code

        # 否则返回HTML错误页面
        return render_template('error.html', error=error), error.status_code

    @app.errorhandler(404)
    def handle_not_found(error):
        """处理404错误"""
        logger.warning("404错误: 页面未找到")

        if request.is_json:
            return jsonify({
                'success': False,
                'error': '页面未找到',
                'status_code': 404
            }), 404

        return render_template('error.html', error=AppError('页面未找到', 404)), 404

    @app.errorhandler(500)
    def handle_internal_error(error):
        """处理500错误"""
        logger.error(f"500错误: {str(error)}")

        if request.is_json:
            return jsonify({
                'success': False,
                'error': '服务器内部错误',
                'status_code': 500
            }), 500

        return render_template('error.html', error=AppError('服务器内部错误', 500)), 500

    @app.errorhandler(Exception)
    def handle_generic_error(error):
        """处理所有其他异常"""
        logger.error(f"未处理的异常: {str(error)}")

        if request.is_json:
            return jsonify({
                'success': False,
                'error': '未知错误',
                'status_code': 500
            }), 500

        return render_template('error.html', error=AppError('未知错误', 500)), 500

from functools import wraps
from flask import request, jsonify
from app.utils.logging import logger

class Validator:
    """数据验证器"""

    @staticmethod
    def validate_required_fields(fields):
        """验证必填字段"""
        def decorator(f):
            @wraps(f)
            def decorated_function(*args, **kwargs):
                # 获取请求数据
                if request.is_json:
                    data = request.get_json()
                else:
                    data = request.form.to_dict()

                # 检查必填字段
                missing_fields = [field for field in fields if field not in data or not data[field]]
                if missing_fields:
                    error_msg = f'缺少必填字段: {", ".join(missing_fields)}'
                    logger.warning(f"数据验证失败: {error_msg}")

                    if request.is_json:
                        return jsonify({
                            'success': False,
                            'error': error_msg
                        }), 400

                    from flask import flash, redirect, url_for
                    flash(error_msg, 'danger')
                    return redirect(url_for('auth.login'))

                return f(*args, **kwargs)
            return decorated_function
        return decorator

    @staticmethod
    def validate_email(email):
        """验证邮箱格式"""
        import re
        email_regex = r'^[^\s@]+@[^\s@]+\.[^\s@]+$'
        return re.match(email_regex, email) is not None

    @staticmethod
    def validate_password_strength(password):
        """验证密码强度"""
        import re
        # 至少8个字符，包含大小写字母、数字和特殊字符
        return (
            len(password) >= 8 and
            re.search(r'[A-Z]', password) and
            re.search(r'[a-z]', password) and
            re.search(r'\d', password) and
            re.search(r'[^A-Za-z0-9]', password)
        )
